    const esc = (value) => String(value ?? '');
    function render(jobs) {
      list.replaceChildren(...jobs.map(job => {
        const item = document.createElement('li'); item.dataset.testid='job-item'; item.dataset.jobId=job.id;
        const heading=document.createElement('strong'); heading.textContent=job.input; item.append(heading,document.createTextNode(' '));
        const status=document.createElement('span'); status.dataset.testid='job-status'; status.textContent=job.status; item.append(status,document.createElement('br'));
        const progress=document.createElement('span'); progress.dataset.testid='job-progress'; progress.textContent=`${job.progress.completed}/${job.progress.total}`; item.append(progress,document.createTextNode(' steps'));
